+    const f = this._refFocusables();
+    if (!f.length) { e.preventDefault(); return; }
+    const path = e.composedPath();
+    const first = f[0], last = f[f.length - 1];
+    const onFirst = path.includes(first);
+    const onLast = path.includes(last);
